unca","observacao":"nunca","gera_plano":false,"pontua":true,"peso":2,"permite_na":true},{"id":"la_of_manter","texto":"Manter as ofertas no próximo dia?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"nunca","gera_plano":false,"pontua":false,"peso":1,"permite_na":true,"condicao":{"item_id":"la_of_sucesso","valores":[true]}},{"id":"la_of_causa","texto":"Qual a causa provável de a ação não ter dado certo?","tipo":"texto","obrigatorio":true,"foto":"nunca","observacao":"nunca","gera_plano":false,"pontua":false,"peso":1,"condicao":{"item_id":"la_of_sucesso","valores":[false]},"ajuda":"Investigue: antecipação, divulgação, ruptura, placa."},{"id":"la_of_antecipacao","texto":"Houve antecipação conforme necessário?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"la_of_radio","texto":"Houve divulgação na rádio?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"la_of_lista","texto":"Houve divulgação na lista de transmissão?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"la_of_ruptura","texto":"Sem ruptura na prateleira e com a placa no local correto?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"la_of_acoes","texto":"Ações corretivas para melhorar a ação do dia anterior (ou nova ação)","tipo":"texto","obrigatorio":true,"foto":"nunca","observacao":"nunca","gera_plano":false,"pontua":false,"peso":1},{"id":"la_of_confirmar","texto":"Oferta do dia seguinte confirmada, com o estoque de todas as lojas conferido","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":3,"permite_na":true,"prazo_hora":"