insert into checklist.modelo_versoes (id, modelo_id, numero, status, conteudo, publicada_em) values (md5('checklist-versao:fiscal_manha:1')::uuid, md5('checklist-modelo:fiscal_manha')::uuid, 1, 'publicada', '{"secoes":[{"id":"operacao","titulo":"Abertura da frente de caixa","setor":"frente_caixa","itens":[{"id":"fm_equip","texto":"Equipamentos do caixa funcionando; limpeza, embalagens, carrinhos e cestinhas; pelo menos uma bobina de reserva","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":2},{"id":"fm_oferta_ciss","texto":"A oferta está lançada no CISS?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true,"ref_ciss":"150006"},{"id":"fm_encarte","texto":"Encarte impresso e colocado em cada caixa (o operador conhece a oferta do dia)?","tipo":"sim_nao","obrigatorio":true,"foto":"sempre","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"fm_avulso","texto":"Produtos da oferta com código avulso informados à equipe de caixa?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"fm_radio","texto":"Rádio da loja com as propagandas da loja (YouTube não é permitido)?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"fm_retornaveis","texto":"A equipe de frente de caixa está atenta às informações das retornáveis?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"fm_telefone","texto":"Telefone da loja sempre com o fiscal?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":