?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"fm_sc_obrigado","texto":"Agradeceu: \"Obrigado por comprar no Super Mix Braz!\"?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true}]}]}'::jsonb, now()) on conflict (id) do nothing;
