unca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"ft_flanela","texto":"Flanela e fita de empacotamento disponíveis?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"ft_telefone","texto":"Telefone da loja sempre com os fiscais?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"ft_cpf_operador","texto":"Operadores orientados a não colocar o próprio CPF na nota do cliente?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true},{"id":"ft_sacola","texto":"Uso da sacola 50×60 orientado e acompanhado?","tipo":"sim_nao","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"permite_na":true}]}]}'::jsonb, now()) on conflict (id) do nothing;
