insert into checklist.modelo_versoes (id, modelo_id, numero, status, conteudo, publicada_em) values (md5('checklist-versao:metodo_polar:1')::uuid, md5('checklist-modelo:metodo_polar')::uuid, 1, 'publicada', '{"secoes":[{"id":"precificacao","titulo":"Precificação","setor":"loja","itens":[{"id":"mp_preco","texto":"Precificação dos produtos expostos: etiqueta embaixo do produto correto","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":2},{"id":"mp_pontas","texto":"Pontas e pontos extras com placa de oferta ou \"Aproveite\"","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":2}]},{"id":"operacao","titulo":"Operação","setor":"loja","itens":[{"id":"mp_pontualidade","texto":"Pontualidade e frequência","tipo":"conformidade","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1},{"id":"mp_deposito","texto":"Organização do depósito; sem mercadoria fora da embalagem","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1},{"id":"mp_avarias","texto":"Sem avarias e perdas por má exposição","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":2,"ajuda":"Perdas por má exposição descontam do valor da meta."},{"id":"mp_vencidos","texto":"Sem produtos vencidos","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":3}]},{"id":"limpeza","titulo":"Limpeza","setor":"loja","itens":[{"id":"mp_limpeza","texto":"Limpeza da seção, dos produtos e dos pontos extras","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":2}]},{"id":"atendimento","titulo":"Atendimento","setor":"frente_caixa","itens":[{"id":"mp_atendimento","texto":"Atendimento ao cliente conforme o script da loja","tipo":"conformidade","obrigatorio":true,"foto":"nunca","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":1,"ajuda":"SUGERIDO: a planilha não tinha itens nesta seção. Ajuste ou remova no próximo rascunho."}]},{"id":"rupturas","titulo":"Rupturas","setor":"loja","itens":[{"id":"mp_rupturas","texto":"Seção sem rupturas (sem buracos na gôndola)","tipo":"conformidade","obrigatorio":true,"foto":"se_nao_conforme","observacao":"se_nao_conforme","gera_plano":true,"pontua":true,"peso":2,"ajuda":"SUGERIDO: a planilha não tinha itens nesta seção. Ajuste ou remova no próximo rascunho."}]}]}'::jsonb, now()) on conflict (id) do nothing;
insert into checklist.historico (tabela, registro_id, acao, depois, justificativa) select 'modelo_versoes', md5('checklist-versao:metodo_polar:1')::uuid, 'publicada', jsonb_build_object('numero', 1, 'origem', 'carga inicial'), 'Planilha 7 MÉTODO POLAR' where not exists (select 1 from checklist.historico where registro_id = md5('checklist-versao:metodo_polar:1')::uuid and acao = 'publicada');
